# scripts/generate_all_500.py
import json
import os
import re

tools = []
seen_ids = set()

def add_t(id, name, cat, desc, func, status, cc, browser, lowend, warnet, vps, apikey, oss, github, site, pros, cons, usecase, diff, money, score):
    clean_id = re.sub(r'[^a-z0-9-_]', '', id.lower())
    if clean_id in seen_ids:
        clean_id = f"{clean_id}-{cat}"
    seen_ids.add(clean_id)
    
    # Validation
    assert status in ['FREE', 'OSS', 'TIER'], f"Invalid status {status} for {id}"
    assert diff in ['Beginner', 'Intermediate', 'Advanced'], f"Invalid diff {diff} for {id}"
    assert money in ['Low', 'Medium', 'High'], f"Invalid money {money} for {id}"
    
    tools.append({
        "id": clean_id,
        "name": name,
        "category": cat,
        "desc": desc,
        "func": func,
        "status": status,
        "cc": bool(cc),
        "browser": bool(browser),
        "lowend": bool(lowend),
        "warnet": warnet,
        "vps": bool(vps),
        "apikey": bool(apikey),
        "oss": bool(oss),
        "github": github or "",
        "site": site or "",
        "pros": pros,
        "cons": cons,
        "usecase": usecase,
        "difficulty": diff,
        "money": money,
        "score": round(float(score), 1),
        "verify": True
    })

